@Service
public class BankAccountService {

    @Autowired
    private AccountRepository accountRepository;

    @Transactional(
        rollbackFor = { InsufficientFundsException.class, SQLException.class },
        noRollbackFor = { AuditLogFailedException.class }
    )
    public void transferFunds(Long sourceId, Long targetId, BigDecimal amount) throws InsufficientFundsException {
        Account source = accountRepository.findById(sourceId).orElseThrow();
        Account target = accountRepository.findById(targetId).orElseThrow();

        source.withdraw(amount);
        target.deposit(amount);

        accountRepository.save(source);
        accountRepository.save(target);

        try {
            // Non-critical audit logging that must not kill the money transfer if it fails
            auditService.logTransfer(sourceId, targetId, amount);
        } catch (AuditLogFailedException e) {
            // Suppressed by noRollbackFor configuration
            throw e;
        }
    }
}
